import { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import { hasSeenGettingStarted, markGettingStartedSeen } from '../lib/persist';
import {
  PERIOD_VALUES,
  activeSectionFor,
  parseLocation,
  pathFor,
  type RouteTarget,
} from '../lib/viewConfig';

export type CollapsedState = Record<string, boolean>;

export type NavTarget = string | { section: string; route?: string | null };

/**
 * Single owner of URL-routable state (T158): shell, active section, time
 * period, and highlighted route. Serialized into the address bar as a REAL
 * PATH (`/measure/reliability?route=36`) — shareable councillor-packet URLs
 * with working Back/forward. Under the Pages demo (no server-side SPA
 * fallback) the same state rides the hash so deep links still resolve:
 * `#/measure/reliability?route=36`.
 *
 * Section keys are the pre-T158 view keys, so every consumer that switches
 * on them (AppHeader pickers, useMapLayers, useTravelPlanner, MapWorkspace)
 * is unchanged.
 *
 * Period behaves as sticky global filter state and is intentionally kept out
 * of the URL: it never re-asserts itself over a Back/forward navigation.
 */
export function useViewRouting(options: {
  savedPeriod: string | null;
  savedHighlightedRoute: string | null;
}) {
  const { savedPeriod, savedHighlightedRoute } = options;

  // One-time parse of the entry URL, before first render. Handles real paths,
  // old `#view` hashes and `?view=` links; legacy keys map through
  // LEGACY_VIEW_MAP.
  const [initial] = useState(() => parseLocation());

  const [shell, setShell] = useState<'home' | 'map' | 'plan' | 'measure' | 'trust'>(() => {
    if (!initial.target.section) return 'home';
    const sec = initial.target.section;
    // shellOf via activeSectionFor keeps this import-light; shells derived
    // from section keys so the smoke test can assert agreement.
    for (const s of ['home', 'map', 'plan', 'measure', 'trust'] as const) {
      if (activeSectionFor(s, sec) === sec) return s;
    }
    return 'home';
  });

  const [section, setSection] = useState<string | null>(() => {
    const sec = initial.target.section;
    if (!sec) return null;
    // Entry with a legacy/unknown section: land the shell's default. The
    // caller-side redirect below rewrites the address bar to canonical.
    return activeSectionFor(
      (['home', 'map', 'plan', 'measure', 'trust'] as const).find(
        (s) => activeSectionFor(s, sec) === sec,
      ) ?? 'home',
      sec,
    );
  });

  const [period, setPeriod] = useState<string>(() => {
    return savedPeriod && PERIOD_VALUES.has(savedPeriod) ? savedPeriod : 'all_day';
  });

  const [highlightedRoute, setHighlightedRoute] = useState<string | null>(
    initial.target.route ?? savedHighlightedRoute,
  );

  const [pendingAnchor, setPendingAnchor] = useState<string | null>(initial.anchor ?? null);

  // Mirrors `section` for the popstate listener below, which is registered
  // once and must not re-bind on every navigation.
  const sectionRef = useRef(section);
  useEffect(() => {
    sectionRef.current = section;
  }, [section]);

  const [showHelp, setShowHelp] = useState(() => !hasSeenGettingStarted());

  const [collapsed, setCollapsed] = useState<CollapsedState>(() => {
    try {
      const raw = localStorage.getItem('miway_sidebar_collapsed');
      return raw ? JSON.parse(raw) : {};
    } catch {
      return {};
    }
  });

  const toggleGroup = useCallback((group: string) => {
    setCollapsed((prev) => {
      const next = { ...prev, [group]: !prev[group] };
      try { localStorage.setItem('miway_sidebar_collapsed', JSON.stringify(next)); } catch {}
      return next;
    });
  }, []);

  const dismissHelp = useCallback(() => {
    setShowHelp(false);
    markGettingStartedSeen();
  }, []);

  // ---- URL write-back (T158) ----------------------------------------------
  // pushState for user navigation (Back/forward traverse views); replaceState
  // for canonicalizing an entered legacy/unknown address (no phantom entry).
  const writeUrl = useCallback(
    (target: RouteTarget, mode: 'push' | 'replace') => {
      const url = pathFor(target);
      // The Pages demo cannot serve /section paths on refresh — keep the
      // shareable shape in the hash there (still real paths after the #).
      const hashMode =
        window.location.pathname.includes('/demo/') ||
        window.location.hostname.endsWith('.github.io');
      if (hashMode) {
        const h = `#${url}`;
        if (mode === 'push') {
          if (window.location.hash !== h) window.location.hash = h; // pushes a history entry
        } else {
          window.history.replaceState(null, '', h);
        }
        return;
      }
      if (mode === 'push') window.history.pushState(null, '', url);
      else window.history.replaceState(null, '', url);
    },
    [],
  );

  // Canonicalize the address on first render when the entry was legacy or
  // missing a section (e.g. bare `/`, `#equity`): no history entry pushed.
  useEffect(() => {
    writeUrl({ section, route: highlightedRoute }, 'replace');
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  useEffect(() => {
    writeUrl({ section, route: highlightedRoute }, 'push');
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [section, highlightedRoute]);

  // Legacy-anchor scroll (ghosttrips -> sq-ghosts etc.).
  useEffect(() => {
    if (!pendingAnchor) return;
    const id = pendingAnchor;
    setPendingAnchor(null);
    requestAnimationFrame(() => {
      document.getElementById(id)?.scrollIntoView({ behavior: 'smooth', block: 'start' });
    });
  }, [pendingAnchor]);

  // Inbound: apply popstate (Back/forward, manual URL edit) to app state.
  useEffect(() => {
    const apply = () => {
      const parsed = parseLocation();
      const sec = parsed.target.section;
      if (!sec) {
        // Bare URL (e.g. Back past the first view): Home.
        setShell('home');
        setSection(null);
      } else {
        setSection(sec);
        for (const s of ['home', 'map', 'plan', 'measure', 'trust'] as const) {
          if (activeSectionFor(s, sec) === sec) { setShell(s); break; }
        }
      }
      setHighlightedRoute(parsed.target.route);
      if (parsed.anchor) setPendingAnchor(parsed.anchor);
    };
    window.addEventListener('popstate', apply);
    return () => window.removeEventListener('popstate', apply);
  }, []);

  // ---- navigation API -------------------------------------------------------
  /** Navigate to a shell, section, or {section, route} target. Accepts:
   *  - a section key ('reliability') — most call sites, pre-T158 semantics;
   *  - a shell key ('home' | 'map' | 'plan' | 'measure' | 'trust') — lands
   *    the shell's default section;
   *  - {section, route} to carry a route highlight in the URL. */
  const navigate = useCallback((target: NavTarget) => {
    if (typeof target === 'string') {
      if (target === 'home') { setShell('home'); setSection(null); return; }
      const landed = activeSectionFor(target as 'map' | 'plan' | 'measure' | 'trust', null);
      if (landed) { setShell(target as 'map' | 'plan' | 'measure' | 'trust'); setSection(landed); return; }
      // Section key (the common case — every pre-T158 call site).
      const owner = (['map', 'plan', 'measure', 'trust'] as const).find((s) => activeSectionFor(s, target) === target);
      if (owner) { setShell(owner); setSection(target); return; }
      return; // unknown token: ignore (URL canonicalization keeps the bar honest)
    }
    const owner = (['map', 'plan', 'measure', 'trust'] as const).find((s) => activeSectionFor(s, target.section) === target.section);
    if (!owner) return;
    setShell(owner);
    setSection(target.section);
    setHighlightedRoute(target.route ?? null);
  }, []);

  const setShellAndDefault = useCallback((next: 'home' | 'map' | 'plan' | 'measure' | 'trust') => {
    navigate(next);
  }, [navigate]);

  const setActiveSection = useCallback((next: string) => {
    setSection(next);
  }, []);

  const effectiveSection = useMemo(
    () => (shell === 'home' ? null : activeSectionFor(shell, section)),
    [shell, section],
  );

  return {
    shell,
    section: effectiveSection,
    setShell: setShellAndDefault,
    setSection: setActiveSection,
    navigate,
    period,
    setPeriod,
    highlightedRoute,
    setHighlightedRoute,
    showHelp,
    setShowHelp,
    dismissHelp,
    collapsed,
    toggleGroup,
  };
}
