interface SourceNoteProps {
  n?: number | string;
  source: string;
  period?: string;
  className?: string;
}

export default function SourceNote({ n, source, period, className = "" }: SourceNoteProps) {
  const parts: string[] = [];
  if (n !== undefined) parts.push(`n=${typeof n === "number" ? n.toLocaleString() : n}`);
  if (period) parts.push(period);
  parts.push(source);
  return (
    <p className={`text-[11px] text-muted mt-1 ${className}`} aria-label="data source">
      {parts.join(" · ")}
    </p>
  );
}
