import { ChevronDown, ChevronRight } from 'lucide-react';
import { HOME_ITEM, SHELLS, type SectionDef, type ShellDef } from '../../lib/viewConfig';

export interface AppSidebarProps {
  shell: 'home' | 'map' | 'plan' | 'measure' | 'trust';
  section: string | null;
  onShell: (shell: 'home' | 'map' | 'plan' | 'measure' | 'trust') => void;
  onSection: (section: string) => void;
  collapsed: Record<string, boolean>;
  toggleGroup: (group: string) => void;
}

/** Dot color encodes the audience: green = measured evidence (Measure),
 * blue = modeled proposals (Map/Plan), grey = start-here / accountability. */
function shellDotColor(shell: ShellDef): string {
  if (shell.key === 'measure') return 'bg-optimized shadow-[0_0_6px_rgba(0,230,118,0.8)]';
  if (shell.key === 'map' || shell.key === 'plan') return 'bg-accent shadow-[0_0_6px_rgba(79,195,247,0.8)]';
  return 'bg-text-muted';
}

/** Badge for sections whose evidentiary basis *differs from their shell's* —
 * the shell header already carries the default ("measured"/"modeled"), so
 * only exceptions get a chip. A "mixed" chip on a modeled shell is the honest
 * signal: real data in, model conclusions out. */
function shellDefaultData(shell: ShellDef): 'measured' | 'modeled' {
  return shell.key === 'measure' ? 'measured' : 'modeled';
}

/** Tooltip + color per exception. "mixed" = measured input, modeled
 * conclusions — check each number's label. */
const DATA_BADGE: Record<string, { label: string; cls: string }> = {
  measured: { label: 'observed', cls: 'bg-optimized/15 text-optimized' },
  modeled: { label: 'modeled', cls: 'bg-accent/15 text-accent' },
  mixed: { label: 'mixed', cls: 'bg-bottleneck/15 text-bottleneck' },
};

function SectionButton({
  section, active, onSelect, shellDefault,
}: {
  section: SectionDef;
  active: boolean;
  onSelect: () => void;
  shellDefault: 'measured' | 'modeled';
}) {
  const measured = section.key === 'servicequality';
  const badge =
    section.data && section.data !== shellDefault ? DATA_BADGE[section.data] : null;
  return (
    <button
      key={section.key}
      onClick={onSelect}
      title={section.tip}
      className={`flex w-full items-start gap-2 rounded-lg py-1.5 pl-7 pr-2.5 text-left transition-all ${
        active
          ? measured
            ? 'nav-active-measured text-text-primary'
            : 'nav-active text-text-primary'
          : 'text-text-secondary hover:bg-card-hover'
      }`}
    >
      <section.Icon
        className={`mt-0.5 h-3.5 w-3.5 shrink-0 ${
          active ? (measured ? 'text-optimized' : 'text-accent') : ''
        }`}
      />
      <span className="min-w-0 flex-1">
        <span className="flex items-center gap-1.5">
          <span className="truncate text-xs font-medium">{section.label}</span>
          {badge && (
            <span className={`shrink-0 rounded px-1 py-px text-[8px] font-bold uppercase ${badge.cls}`}>
              {badge.label}
            </span>
          )}
          {section.wip && (
            <span
              title={section.wipNote ?? 'Experimental section'}
              className="shrink-0 rounded bg-bottleneck/15 px-1 py-px text-[8px] font-bold uppercase text-bottleneck"
            >
              exp
            </span>
          )}
        </span>
        <span className="block truncate text-[10px] text-text-muted">{section.desc}</span>
      </span>
    </button>
  );
}

/** Left navigation (T158): Home, then the five shells with their sections
 * nested underneath. Pure presentation — all state is owned by App. */
export default function AppSidebar({
  shell, section, onShell, onSection, collapsed, toggleGroup,
}: AppSidebarProps) {
  const homeActive = shell === 'home';
  const homeBadge = HOME_ITEM.data && HOME_ITEM.data !== 'modeled' ? DATA_BADGE[HOME_ITEM.data] : null;
  return (
    <nav className="flex w-64 shrink-0 flex-col gap-1 overflow-y-auto border-r border-border bg-card p-2">
      <button
        onClick={() => onShell('home')}
        title={HOME_ITEM.tip}
        className={`flex w-full items-start gap-2.5 rounded-lg px-2.5 py-2 text-left transition-all ${
          homeActive ? 'nav-active text-text-primary' : 'text-text-secondary hover:bg-card-hover'
        }`}
      >
        <HOME_ITEM.Icon className={`mt-0.5 h-4 w-4 shrink-0 ${homeActive ? '' : ''}`} />
        <span className="min-w-0 flex-1">
          <span className="flex items-center gap-1.5">
            <span className="truncate text-xs font-medium">{HOME_ITEM.label}</span>
            {homeBadge && (
              <span className={`shrink-0 rounded px-1 py-px text-[8px] font-bold uppercase ${homeBadge.cls}`}>
                {homeBadge.label}
              </span>
            )}
          </span>
          <span className="block truncate text-[10px] text-text-muted">{HOME_ITEM.desc}</span>
        </span>
      </button>

      {SHELLS.map((s) => {
        const isCollapsed = !!collapsed[s.key];
        const hasActive = shell === s.key;
        const dotColor = shellDotColor(s);
        const shellDefault = shellDefaultData(s);
        return (
          <div key={s.key}>
            <button
              onClick={() => onShell(s.key)}
              className={`flex w-full items-center gap-1.5 px-2.5 pb-1 pt-2.5 text-[10px] font-bold uppercase tracking-wider transition-colors ${
                hasActive ? 'text-text-primary' : 'text-text-muted hover:text-text-secondary'
              }`}
            >
              <span className={`h-1.5 w-1.5 shrink-0 rounded-full ${dotColor}`} />
              <s.Icon className="h-3.5 w-3.5 shrink-0" />
              <span className="flex-1 text-left">{s.label}</span>
              <span
                role="button"
                aria-label={`Toggle ${s.label} sections`}
                tabIndex={-1}
                onClick={(e) => {
                  e.stopPropagation();
                  toggleGroup(s.key);
                }}
                className="-mr-1 rounded p-0.5 hover:bg-card-hover"
              >
                {isCollapsed ? <ChevronRight className="h-3 w-3" /> : <ChevronDown className="h-3 w-3" />}
              </span>
            </button>
            {!isCollapsed &&
              s.sections.map((sec) => (
                <SectionButton
                  key={sec.key}
                  section={sec}
                  active={hasActive && section === sec.key}
                  onSelect={() => onSection(sec.key)}
                  shellDefault={shellDefault}
                />
              ))}
          </div>
        );
      })}
    </nav>
  );
}
