import { useEffect, useState } from 'react';
import { api } from '../lib/api';
import type { DataVintageResponse, DataSourceVintage } from '../types';

export type Vintages = Record<string, DataSourceVintage>;

/**
 * Data vintages for the headline-number badges (loaded once per mount).
 *
 * Returns an empty map while loading or if the endpoint is unavailable, so
 * panels render exactly as before — the badge is additive, never blocking.
 */
export function useDataVintages(): Vintages {
  const [vintages, setVintages] = useState<Vintages>({});
  useEffect(() => {
    let cancelled = false;
    // Guarded call: test mocks (and any older API build) may not expose
    // dataVintage at all — the badge is additive and must never crash a panel.
    const fetcher = api.dataVintage as (() => Promise<DataVintageResponse>) | undefined;
    if (typeof fetcher !== 'function') return;
    fetcher
      .call(api)
      .then((d: DataVintageResponse) => {
        if (cancelled) return;
        const out: Vintages = {};
        for (const [k, v] of Object.entries(d)) {
          if (k !== 'generated_at' && typeof v === 'object' && v !== null) {
            out[k] = v as DataSourceVintage;
          }
        }
        setVintages(out);
      })
      .catch(() => {
        /* badge is optional; a failed fetch just leaves it off */
      });
    return () => {
      cancelled = true;
    };
  }, []);
  return vintages;
}

function ageLabel(minutes: number | null | undefined): string {
  if (minutes == null) return 'age unknown';
  if (minutes < 2) return 'just now';
  if (minutes < 60) return `${minutes} min old`;
  const h = Math.floor(minutes / 60);
  if (h < 24) return `${h} h ${minutes % 60} min old`;
  const d = Math.floor(h / 24);
  return `${d} d ${h % 24} h old`;
}

/** Short human label for a vintage, e.g. "12 min old" or "missing". */
export function vintageLabel(v: DataSourceVintage | undefined): string {
  if (!v) return '';
  if (!v.exists) return 'no data file';
  return ageLabel(v.age_minutes);
}

/** True when an analysis output is meaningfully behind its raw input. */
export function isStale(v: DataSourceVintage | undefined): boolean {
  return (v?.input_lag_minutes ?? 0) > 30;
}
