import { useCallback, useState } from 'react';
import { savedNum, type PersistedAppState, type ServiceDay, type VolumeMode } from '../lib/persist';
import type { OptimizeRequest, TimePeriod } from '../types';

/**
 * Single owner of the optimizer's control state: the values behind the
 * OptimizePanel sliders, the service day, the ridership weighting, and the
 * `buildRequest` payload derived from them (shared with the travel planner).
 * Hydrates defaults from persisted state once, at mount.
 */
export function useOptimizerSettings(saved: Partial<PersistedAppState> | null) {
  const [maxShift, setMaxShift] = useState(saved?.maxShift ?? 5);
  const [bufferMinutes, setBufferMinutes] = useState(saved?.bufferMinutes ?? 2);
  const [highFreqCutoff, setHighFreqCutoff] = useState(saved?.highFreqCutoff ?? 10);
  const [tMax, setTMax] = useState(() => savedNum(saved, 'tMax', 12));
  const [maxConnections] = useState(() => savedNum(saved, 'maxConnections', 6000));
  // Default 30 s, matching the backend's OptimizeRequest default: measured on
  // the real feed, incumbents plateau by ~18 s and All Day certifies before
  // 30 s, so 60 s bought waiting, not quality. Explicit fields win over the
  // period presets on the backend — so the default itself had to change here.
  const [timeLimitSeconds, setTimeLimitSeconds] = useState(() => savedNum(saved, 'timeLimitSeconds', 30));
  const [minLayoverMinutes, setMinLayoverMinutes] = useState(() => savedNum(saved, 'minLayoverMinutes', 8));
  const [serviceDay, setServiceDay] = useState<ServiceDay>(saved?.serviceDay ?? 'weekday');
  // ``measured`` was removed from the UI (its data file never existed, so it
  // silently fell back to frequency weights); a saved setting from an older
  // session is normalized to ``ridership``, the honest real-data option.
  const [volumeMode, setVolumeMode] = useState<VolumeMode>(
    saved?.volumeMode === 'measured' ? 'ridership' : (saved?.volumeMode ?? 'ridership'),
  );

  const buildRequest = useCallback(
    (period: string, periods: Record<string, TimePeriod> | null): OptimizeRequest => {
      const win = periods?.[period] ?? { start: 360, end: 1320 };
      return {
        max_shift: maxShift,
        buffer_minutes: bufferMinutes,
        high_freq_cutoff: highFreqCutoff,
        t_max: tMax,
        service_day: serviceDay,
        volume_mode: volumeMode,
        window_start: win.start,
        window_end: win.end,
        max_connections: maxConnections,
        time_limit_seconds: timeLimitSeconds,
        min_layover_minutes: minLayoverMinutes,
        period,
      };
    },
    [maxShift, bufferMinutes, highFreqCutoff, tMax, serviceDay, volumeMode, maxConnections, timeLimitSeconds, minLayoverMinutes],
  );

  return {
    maxShift, setMaxShift,
    bufferMinutes, setBufferMinutes,
    highFreqCutoff, setHighFreqCutoff,
    tMax, setTMax,
    maxConnections,
    timeLimitSeconds, setTimeLimitSeconds,
    minLayoverMinutes, setMinLayoverMinutes,
    serviceDay, setServiceDay,
    volumeMode, setVolumeMode,
    buildRequest,
  };
}
