import { Suspense, useEffect, useRef, useState } from 'react';
import { AlertTriangle } from 'lucide-react';

export interface StackedSection {
  key: string;
  label: string;
  desc: string;
  /** Section-level evidence badge, matching the sidebar chip. */
  data?: 'measured' | 'modeled' | 'mixed';
  wip?: boolean;
  wipNote?: string;
  /** Renders the section's panel (a lazy component already prop-wired by App). */
  Body: () => React.ReactNode;
  /** Max-width wrapper (cards) vs full-width (map-backed panels). */
  wide?: boolean;
}

const BADGE_CLS: Record<string, string> = {
  measured: 'bg-optimized/15 text-optimized',
  modeled: 'bg-accent/15 text-accent',
  mixed: 'bg-bottleneck/15 text-bottleneck',
};
const BADGE_LABEL: Record<string, string> = {
  measured: 'observed',
  modeled: 'modeled',
  mixed: 'mixed',
};

/** One section in a stacked shell: header band + lazily-mounted panel body.
 * Bodies mount on first activation (React.lazy per section = the old
 * per-panel chunk splitting) and stay mounted while siblings are visited —
 * so switching sections back and forth doesn't refetch. */
function StackedSectionBody({
  section, active,
}: {
  section: StackedSection;
  active: boolean;
}) {
  const [mounted, setMounted] = useState(false);
  const ref = useRef<HTMLDivElement>(null);
  useEffect(() => {
    if (active) setMounted(true);
  }, [active]);

  // Inactive sections collapse to their header; on activation the section
  // scrolls to the top of the shell like a page change.
  useEffect(() => {
    if (active && ref.current) {
      const top = ref.current.offsetTop;
      const scroller = ref.current.closest('[data-section-scroller]');
      if (scroller && Math.abs(scroller.scrollTop - top) > 8) scroller.scrollTo({ top, behavior: 'smooth' });
    }
  }, [active]);

  return (
    <div ref={ref} data-section={section.key} className={active ? '' : 'hidden'}>
      <div className="sticky top-0 z-10 -mx-2 mb-2 flex items-center gap-2 border-b border-border bg-bg/95 px-2 py-2 backdrop-blur">
        <h2 className="text-base font-bold text-text-primary">{section.label}</h2>
        {section.data && (
          <span
            title={`${BADGE_LABEL[section.data]} basis`}
            className={`rounded px-1.5 py-0.5 text-[9px] font-bold uppercase ${BADGE_CLS[section.data]}`}
          >
            {BADGE_LABEL[section.data]}
          </span>
        )}
        {section.wip && (
          <span title={section.wipNote ?? 'Experimental section'} className="flex items-center gap-1 rounded bg-bottleneck/15 px-1.5 py-0.5 text-[9px] font-bold uppercase text-bottleneck">
            <AlertTriangle className="h-3 w-3" /> experimental
          </span>
        )}
        <span className="hidden text-[10px] text-text-muted sm:block">{section.desc}</span>
      </div>
      {mounted && (
        <div className={section.wide ? 'pb-6' : 'mx-auto max-w-3xl pb-6'}>
          <Suspense
            fallback={
              <div className="flex items-center justify-center p-8 text-text-muted" role="status" aria-label={`Loading ${section.label}`}>
                <div className="h-6 w-6 animate-spin rounded-full border-2 border-border border-t-accent" />
              </div>
            }
          >
            {section.Body()}
          </Suspense>
        </div>
      )}
    </div>
  );
}

/**
 * Stacked shell for Measure/Trust (T158): each former view renders as a
 * full section with its own header + evidence badge; exactly one is open.
 * Keeps a single scroller so sticky headers and section-anchored scrolls
 * behave like pages inside one document.
 */
export default function SectionStack({ sections, active }: { sections: StackedSection[]; active: string | null }) {
  const current = sections.find((s) => s.key === active) ?? sections[0];
  return (
    <div data-section-scroller className="flex-1 overflow-y-auto">
      <div className="mx-auto w-full px-2">
        {sections.map((s) => (
          <StackedSectionBody key={s.key} section={s} active={s === current} />
        ))}
      </div>
    </div>
  );
}
